$ErrorActionPreference="Stop"

$Campaign="D:\MT5_Backtests\guardian-autonomous-main\research\campaigns\EDGE_ATLAS_2026_09_17"
$ExpectedZipHash="ba991ab5eb980fd7b7354aa6a6511c72758d1ca9f2baffafab177daa7225ef13"
$ZipB64=@'

'@

$Tmp=Join-Path $env:TEMP ("night_atlas_v1_"+[guid]::NewGuid().ToString("N"))
$Zip=Join-Path $Tmp "night_atlas_v1.zip"
$Expand=Join-Path $Tmp "expanded"

New-Item -ItemType Directory -Force -Path $Tmp|Out-Null
New-Item -ItemType Directory -Force -Path $Expand|Out-Null
New-Item -ItemType Directory -Force -Path $Campaign|Out-Null

try {
    [IO.File]::WriteAllBytes($Zip,[Convert]::FromBase64String($ZipB64))
    $h=(Get-FileHash $Zip -Algorithm SHA256).Hash.ToLower()
    if($h-ne $ExpectedZipHash){throw "NIGHT ATLAS bundle hash mismatch"}
    Expand-Archive -Path $Zip -DestinationPath $Expand -Force

    $sums=Get-Content (Join-Path $Expand "SHA256SUMS.json") -Raw|ConvertFrom-Json
    foreach($p in $sums.PSObject.Properties){
        $src=Join-Path $Expand $p.Name
        if(-not(Test-Path $src)){throw "Missing bundle file: $($p.Name)"}
        $actual=(Get-FileHash $src -Algorithm SHA256).Hash.ToLower()
        if($actual-ne ([string]$p.Value).ToLower()){throw "Hash mismatch: $($p.Name)"}
    }

    foreach($n in @("night_atlas_v1.py","night_atlas_analyze_v1.py","night_atlas_cross_scan_v1.py","run_night_atlas_v1.ps1")){
        Copy-Item (Join-Path $Expand $n) (Join-Path $Campaign $n) -Force
    }

    foreach($n in @("night_atlas_v1.py","night_atlas_analyze_v1.py","night_atlas_cross_scan_v1.py")){
        python -m py_compile (Join-Path $Campaign $n)
        if($LASTEXITCODE-ne 0){throw "Python syntax check failed: $n"}
    }

    Write-Host ""
    Write-Host "============================================================"
    Write-Host " GUARDIAN NIGHT ATLAS V1 INSTALLED"
    Write-Host "============================================================"
    Write-Host "CAMPAIGN : $Campaign"
    Write-Host "FAMILIES : 17 / variants 22"
    Write-Host "DISCOVERY: 2017-2022"
    Write-Host "2023+    : CLOSED"
    Write-Host "2026     : CLOSED"
    Write-Host ""
    Write-Host "RUN:"
    Write-Host "powershell -ExecutionPolicy Bypass -File `"$Campaign\run_night_atlas_v1.ps1`""
    Write-Host "============================================================"
}
finally {
    if(Test-Path $Tmp){Remove-Item $Tmp -Recurse -Force}
}
